'use strict';
const products=window.PRODUCTS;
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const money=n=>'₹'+n.toLocaleString('en-IN');
const getProduct=id=>products.find(p=>p.id===id);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cart=[];try{const saved=JSON.parse(localStorage.getItem('drmz-cart-v1')||'[]');if(Array.isArray(saved))cart=saved.filter(x=>x&&getProduct(x.id)&&Number.isInteger(x.qty)&&x.qty>0).map(x=>({id:x.id,qty:Math.min(x.qty,99)}));}catch{}
let slide=0,category='all',selectedProduct=null,toastTimer;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function persistCart(){try{localStorage.setItem('drmz-cart-v1',JSON.stringify(cart));}catch{notify('Your browser could not save the cart. It will remain available during this visit.');}renderCart();}
function addCart(id,qty=1){const p=getProduct(id);if(!p)return;const row=cart.find(x=>x.id===id);if(row)row.qty=Math.min(99,row.qty+qty);else cart.push({id,qty:Math.max(1,Math.min(99,qty))});persistCart();notify(`${p.name} added to your cart`);}
function openDialog(id){$$('dialog[open]').forEach(d=>d.close());$(id).showModal();}
function card(p,badge=''){return `<article class="product-card"><div class="product-visual"><a href="#product/${p.id}" class="product-photo ${p.hero?'is-cutout':''}" aria-label="View ${escapeHTML(p.name)}"><img src="${p.image}" alt="${escapeHTML(p.name)} scale model" loading="lazy">${badge?`<span class="product-badge">${badge}</span>`:''}</a><button class="quick-add" data-add="${p.id}" aria-label="Add ${escapeHTML(p.name)} to cart">+</button></div><p class="product-meta">${p.scale} SCALE · ${p.category==='F1'?'MOTORSPORT':'DIECAST MODEL'}</p><h3><a href="#product/${p.id}">${escapeHTML(p.name)}</a></h3><p class="product-price">${money(p.price)} <s>${money(p.original)}</s></p></article>`;}
$('#featured-grid').innerHTML=[products[0],...products.slice(8,11)].map((p,i)=>card(p,i===0?'GARAGE PICK':'')).join('');
$('#large-grid').innerHTML=products.filter(p=>p.category==='1:18').slice(1,5).map(p=>card(p)).join('');
$('#f1-grid').innerHTML=products.filter(p=>p.category==='F1').map(p=>card(p)).join('');
$('#slide-dots').innerHTML=products.slice(0,8).map((p,i)=>`<button data-slide="${i}" aria-label="Show ${escapeHTML(p.name)}" aria-current="${i===0}"></button>`).join('');
function renderSlide(animate=true){const p=products[slide];$('#hero-index').textContent=String(slide+1).padStart(2,'0');$('#hero-brand').textContent=p.brand;$('#hero-name').textContent=p.model;$('#hero-word').textContent=p.brand;$('#hero-description').textContent=p.description;$('#hero-price').textContent=money(p.price);$('#hero-original').textContent=money(p.original);$('#hero-discount').textContent=Math.round((1-p.price/p.original)*100)+'% off';$('#hero-image').src=p.hero;$('#hero-reflection').src=p.hero;$('#previous-image').src=products[(slide+7)%8].hero;$('#next-image').src=products[(slide+1)%8].hero;$$('[data-slide]').forEach((d,i)=>d.setAttribute('aria-current',String(i===slide)));if(animate){for(const [el,cls]of[[$('#main-car'),'car-enter'],[$('#hero-details'),'slide-enter'],[$('.hero-purchase'),'slide-enter']]){el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);}}}
function changeSlide(diff){slide=(slide+diff+8)%8;renderSlide();}
$('#prev').onclick=()=>changeSlide(-1);$('#next').onclick=()=>changeSlide(1);$('#hero-add').onclick=()=>addCart(products[slide].id);$('#hero-view').onclick=()=>location.hash='product/'+products[slide].id;
$('#showroom').addEventListener('keydown',e=>{if(e.target!==$('#showroom'))return;if(e.key==='ArrowRight'){e.preventDefault();changeSlide(1);}if(e.key==='ArrowLeft'){e.preventDefault();changeSlide(-1);}});
let pointerStart=null;
$('#showroom').addEventListener('pointerdown',e=>{if(e.target.closest('button,a'))return;pointerStart={x:e.clientX,y:e.clientY};});
$('#showroom').addEventListener('pointerup',e=>{if(!pointerStart)return;const dx=e.clientX-pointerStart.x,dy=e.clientY-pointerStart.y;pointerStart=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy))changeSlide(dx<0?1:-1);});
$('#showroom').addEventListener('pointercancel',()=>pointerStart=null);
renderSlide(false);
function showProduct(id){const p=getProduct(id);if(!p){notify('This model could not be found.');return;}selectedProduct=p;$('#product-content').innerHTML=`<div class="product-detail"><div class="detail-image"><img src="${p.image}" alt="${escapeHTML(p.name)}"></div><div class="detail-copy"><span class="eyebrow">DRMZ ON POCKETS / ${p.scale}</span><h2>${escapeHTML(p.name).toUpperCase()}</h2><div class="product-price">${money(p.price)} <s>${money(p.original)}</s></div><p>${escapeHTML(p.description)}</p><div class="detail-specs"><span>${p.scale} SCALE</span><span>${p.category==='F1'?'MOTORSPORT':'DIECAST'}</span><span>AS PICTURED</span></div><div class="quantity-row"><label for="product-qty">Quantity</label><div class="quantity-control"><button data-qty="-1" aria-label="Decrease quantity">−</button><input id="product-qty" type="number" min="1" max="99" value="1" inputmode="numeric"><button data-qty="1" aria-label="Increase quantity">+</button></div></div><button class="button solid" id="detail-add">ADD TO CART — ${money(p.price)}</button><p class="detail-note">Preview model and sample price. Stock, specifications and final pricing will be confirmed before the store accepts orders.</p></div></div>`;openDialog('#product-dialog');}
function searchResults(){const q=$('#global-search').value.trim().toLowerCase();const matches=products.filter(p=>`${p.name} ${p.scale} ${p.category}`.toLowerCase().includes(q));$('#search-caption').textContent=q?`${matches.length} model${matches.length===1?'':'s'} found`:'Explore the garage';$('#search-results').innerHTML=matches.slice(0,q?18:6).map(p=>`<button class="search-result" data-product="${p.id}"><img src="${p.image}" alt=""><span><b>${escapeHTML(p.name)}</b><small>${p.scale} · ${money(p.price)}</small></span></button>`).join('')||'<p>No models found. Try a brand name or a scale.</p>';}
$('#global-search').addEventListener('input',searchResults);
function showSearch(){openDialog('#search-dialog');$('#global-search').value='';searchResults();$('#global-search').focus();}
const categoryTitles={all:'ALL MODELS','1:24':'1:24 DIECAST','1:18':'1:18 BIG SIZE',F1:'THE F1 GARAGE',RC:'THE RC GARAGE',gifts:'GIFTS UNDER ₹2,500'};
function renderCatalog(){const q=$('#catalog-search').value.trim().toLowerCase();let list=products.filter(p=>(category==='all'||(category==='gifts'?p.price<=2500:p.category===category))&&`${p.name} ${p.scale}`.toLowerCase().includes(q));const sort=$('#sort').value;if(sort==='price-low')list.sort((a,b)=>a.price-b.price);if(sort==='price-high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#catalog-grid').innerHTML=list.map(p=>card(p)).join('');$('#result-count').textContent=`${list.length} model${list.length===1?'':'s'}`;$('#empty-collection').hidden=list.length>0;$('#empty-collection').innerHTML=category==='RC'?'<h2>THE RC GARAGE IS WARMING UP.</h2><p>Remote control models are on the way. The collection will appear here when the catalogue is ready.</p><a class="button solid" href="#collection/all">EXPLORE DIECAST MODELS →</a>':'<h2>NO MODELS FOUND.</h2><p>Try another search or explore a different scale.</p><button class="button outline" data-action="reset-search">CLEAR SEARCH</button>';}
function showCollection(cat){category=categoryTitles[cat]?cat:'all';$('#home-view').hidden=true;$('#collection-view').hidden=false;$('#collection-title').textContent=categoryTitles[category];$('#collection-description').textContent=category==='RC'?'A new kind of play. Coming to your garage soon.':'Discover your next shelf favourite.';$('#collection-filters').innerHTML=Object.entries({all:'All models','1:24':'1:24','1:18':'1:18 Big',F1:'F1',RC:'RC'}).map(([key,label])=>`<a href="#collection/${key}" class="chip ${category===key?'active':''}">${label}</a>`).join('');$('#catalog-search').value='';$('#sort').value='featured';renderCatalog();window.scrollTo({top:0,behavior:'instant'});}
$('#catalog-search').addEventListener('input',renderCatalog);$('#sort').addEventListener('change',renderCatalog);
let pageHash='#home',handlingRoute=false;
function route(){handlingRoute=true;const hash=decodeURIComponent(location.hash||'#home');if(hash==='#main'){handlingRoute=false;return;}if(hash.startsWith('#product/')){showProduct(hash.split('/')[1]);}else{$$('dialog[open]').forEach(d=>d.close());pageHash=hash;if(hash.startsWith('#collection/'))showCollection(hash.split('/')[1]);else{$('#home-view').hidden=false;$('#collection-view').hidden=true;window.scrollTo({top:0,behavior:'instant'});}}$('#nav').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');handlingRoute=false;}
window.addEventListener('hashchange',route);
$('#product-dialog').addEventListener('close',()=>{if(!handlingRoute&&location.hash.startsWith('#product/'))history.replaceState(null,'',pageHash);});
function renderCart(){const count=cart.reduce((s,x)=>s+x.qty,0);$('#cart-count').textContent=count;$('.cart-button').setAttribute('aria-label',`Open shopping cart, ${count} items`);$('#drawer-count').textContent=`(${count})`;$('#cart-items').innerHTML=cart.length?cart.map(x=>{const p=getProduct(x.id);return `<article class="cart-item"><img src="${p.image}" alt="${escapeHTML(p.name)}"><div><h3>${escapeHTML(p.name)}</h3><p class="cart-meta">${p.scale} · As pictured</p><div class="item-bottom"><div class="quantity-control"><button data-cart-change="${p.id}" data-delta="-1" aria-label="Decrease ${escapeHTML(p.name)} quantity">−</button><span>${x.qty}</span><button data-cart-change="${p.id}" data-delta="1" aria-label="Increase ${escapeHTML(p.name)} quantity" ${x.qty>=99?'disabled':''}>+</button></div><span class="cart-item-price">${money(p.price*x.qty)}</span></div><button class="remove-item" data-remove="${p.id}">Remove</button></div></article>`;}).join(''):'<div class="empty-state"><h2>ROOM FOR YOUR<br>NEXT FAVOURITE.</h2><p>Your cart is empty. Explore the garage and find a model you love.</p><button class="button solid" data-action="continue">EXPLORE THE COLLECTION →</button></div>';const total=cart.reduce((s,x)=>s+getProduct(x.id).price*x.qty,0);$('#cart-summary').innerHTML=cart.length?`<div class="cart-summary"><div class="cart-total"><span>Subtotal</span><span>${money(total)}</span></div><p>Sample prices. Delivery and taxes are not calculated.<br>Your cart is saved on this device.</p><button class="button solid" data-action="checkout">CHECKOUT →</button><button class="button outline" data-action="download">DOWNLOAD YOUR SELECTION</button></div>`:'';}
const info={about:{title:'DRMZ ON POCKETS',html:'<span class="eyebrow">COLLECT. PLAY. PASSION.</span><p>A place for car lovers to build a miniature version of their dream garage. The DRMZ storefront brings diecast models and remote control cars together under the brand you shared.</p><p>This preview uses sample catalogue content to demonstrate the design and shopping experience.</p>'},shipping:{title:'SHIPPING & RETURNS',html:'<p>Delivery areas, shipping charges and return terms will be published when the DRMZ store is ready to accept orders.</p><p>No shipping or return promises apply to this preview catalogue. No orders or payments can be submitted here.</p>'},privacy:{title:'YOUR PRIVACY',html:'<p>This storefront saves your cart in local storage on this browser and device. Cart selections are not sent to a shop server.</p><p>This version does not collect account, address, email or payment information. Clearing your browser’s site data removes the saved cart.</p>'},contact:{title:'THE STORE IS TAKING SHAPE.',html:'<p>You are viewing the DRMZ storefront preview. Official contact details, product inventory and customer support information will be added before launch.</p><p>For now, you can explore models, compare scales and save a selection in your cart.</p>'},checkout:{title:'YOUR GARAGE IS SAVED.',html:'<span class="eyebrow">STOREFRONT PREVIEW</span><p>Checkout is not connected yet, so this site cannot take payment or place an order. Your selection is safely saved in this browser.</p><p>Download your selection for reference, or continue exploring the models.</p><button class="button solid" data-action="download">DOWNLOAD YOUR SELECTION</button>'}};
function showInfo(key){const i=info[key]||info.about;$('#info-title').textContent=i.title;$('#info-content').innerHTML=i.html;openDialog('#info-dialog');}
function showGuide(){$('#info-title').textContent='FIND YOUR SCALE.';$('#info-content').innerHTML='<p>The scale tells you how much smaller a model is than its real-world counterpart. A smaller second number means a bigger model of the same car.</p><table class="scale-table"><thead><tr><th>SCALE</th><th>TYPICAL LENGTH*</th><th>GREAT FOR</th></tr></thead><tbody><tr><td><b>1:18</b></td><td>24–30 cm</td><td>A shelf centrepiece</td></tr><tr><td><b>1:24</b></td><td>17–22 cm</td><td>Desk-sized collections</td></tr><tr><td><b>1:43</b></td><td>9–13 cm</td><td>A miniature racing grid</td></tr></tbody></table><p><small>*Approximate sizes. The exact length depends on the real car and the model manufacturer.</small></p><a href="#collection/all" class="button solid">EXPLORE ALL MODELS →</a>';openDialog('#info-dialog');}
function downloadSelection(){if(!cart.length){notify('Add a model to your cart first.');return;}const lines=['DRMZ ON POCKETS — YOUR GARAGE','Sample catalogue selection — this is not an order',''];cart.forEach(x=>{const p=getProduct(x.id);lines.push(`${p.name} | ${p.scale} | Qty ${x.qty} | ${money(p.price*x.qty)}`);});lines.push('',`Sample subtotal: ${money(cart.reduce((s,x)=>s+getProduct(x.id).price*x.qty,0))}`,'Prices and availability must be confirmed before purchase.');const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='drmz-your-garage.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Your selection has been downloaded.');}
$('#menu-button').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(open));};
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.matches('[data-close]'))t.closest('dialog').close();if(t.dataset.add)addCart(t.dataset.add);if(t.dataset.slide!==undefined){slide=Number(t.dataset.slide);renderSlide();}if(t.dataset.product){const hash='#product/'+t.dataset.product;if(location.hash===hash)showProduct(t.dataset.product);else location.hash=hash;}if(t.dataset.qty){const input=$('#product-qty');input.value=Math.max(1,Math.min(99,(Number(input.value)||1)+Number(t.dataset.qty)));}if(t.id==='detail-add'){const qty=Math.max(1,Math.min(99,Math.floor(Number($('#product-qty').value)||1)));$('#product-qty').value=qty;addCart(selectedProduct.id,qty);}if(t.dataset.cartChange){const row=cart.find(x=>x.id===t.dataset.cartChange);if(row)row.qty=Math.max(0,Math.min(99,row.qty+Number(t.dataset.delta)));cart=cart.filter(x=>x.qty>0);persistCart();}if(t.dataset.remove){cart=cart.filter(x=>x.id!==t.dataset.remove);persistCart();}switch(t.dataset.action){case'search':showSearch();break;case'cart':renderCart();openDialog('#cart-dialog');break;case'guide':showGuide();break;case'info':showInfo(t.dataset.info);break;case'checkout':showInfo('checkout');break;case'download':downloadSelection();break;case'continue':$('#cart-dialog').close();if(location.hash==='#collection/all')route();else location.hash='collection/all';break;case'reset-search':$('#catalog-search').value='';renderCatalog();break;}});
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
renderCart();route();
